15: export const useAsyncTask = (effect, deps) => {
16:   const dispatch = useDispatch();
17:   useEffect(() => {
18:     const controller = new AbortController();
19:     let cleanup;
20:     effect({ signal: controller.signal })
21:       .then((result) => {
22:         cleanup = result;
23:       })
24:       .catch((error) => {
