44: export const useCatchCallback = (method, deps) => {
45:   const dispatch = useDispatch();
46:   return useCallback(
47:     (...parameters) => {
48:       method(...parameters).catch((error) => dispatch(errorsActions.push(error.message)));
49:     },
50:     // eslint-disable-next-line @eslint-react/exhaustive-deps
51:     deps,
52:   );
53: };
